using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.SignalR;
namespace Society.Api;
public class CommunicationService(AppDb db,Access a,MembershipService membership,CommunityService community,IConfiguration config){
 public static readonly string[] Permissions=["communications.send","communications.approve","communications.inbox","communications.groups","communications.moderate","communications.templates","communications.accounts","communications.automations","communications.analytics","communications.settings","communications.highvolume"];
 public static readonly string[] Channels=["InApp","Email","SMS","WhatsApp"];
 public static readonly string[] Variables=["member_name","chapter_name","region_name","society_name","officer_name","event_name","event_date","event_venue","rsvp_link",..FinanceCommunication.Variables];
 public static readonly string[] Triggers=["MemberApplicationReceived","MemberApproved","MemberActivated","MemberBirthday","WeddingAnniversary","MembershipAnniversary","EventPublished","EventInvitationIssued","RsvpPending","RegistrationConfirmed","EventApproaching","EventCancelled","OfficerAppointmentApproved","OfficerTermExpiring","AnnouncementPublished","Recurring"];
 public static async Task Seed(AppDb db,Guid tenant){db.Add(new CommunicationPolicy{TenantId=tenant});foreach(var name in new[]{"Welcome Member","Application Approved","Application Rejected","Member Activation","Chapter Announcement","Regional Announcement","Society Circular","Event Invitation","RSVP Reminder","Event Registration Confirmation","Event Cancellation","Birthday Greeting","Wedding Anniversary Greeting","Membership Anniversary","Officer Appointment","Leadership Transition","Meeting Notice"})db.Add(new CommunicationTemplate{TenantId=tenant,Name=name,Category=name,Body=MemberGreetings.Defaults.FirstOrDefault(g=>g.Name==name).Body??"Hello {{member_name}},\n"+name+" from {{society_name}}.",Subject=MemberGreetings.Defaults.FirstOrDefault(g=>g.Name==name).Subject??name});await Task.CompletedTask;}
 public Task<CommunicationPolicy> Policy(Guid tenant)=>db.Set<CommunicationPolicy>().AsNoTracking().SingleAsync(p=>p.TenantId==tenant);
 public async Task<CommunicationPreference> Preference(Guid tenant,Guid user)=>await db.Set<CommunicationPreference>().AsNoTracking().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.UserId==user)??new(){TenantId=tenant,UserId=user};
 public static bool ChannelAllowed(CommunicationPreference p,string channel)=>channel switch{"InApp"=>p.InApp,"Email"=>p.Email,"SMS"=>p.Sms,"WhatsApp"=>p.WhatsApp,_=>false};
 public static void ValidateTemplate(string body){if(body.Length>12000||body.Contains('\0'))throw new DomainException("Template exceeds its text limit");foreach(Match match in Regex.Matches(body,@"\{\{\s*([^{}]+?)\s*\}\}"))if(!Variables.Contains(match.Groups[1].Value))throw new DomainException("Unknown template variable: "+match.Groups[1].Value);if(body.Contains("<script",StringComparison.OrdinalIgnoreCase))throw new DomainException("Scripts are not supported");}
 public static string Render(string body,Dictionary<string,string> variables)=>Regex.Replace(body,@"\{\{\s*([^{}]+?)\s*\}\}",m=>variables.GetValueOrDefault(m.Groups[1].Value,""));
 public async Task<bool> Blocked(Guid tenant,Guid first,Guid second)=>await db.Set<CommunityBlock>().AnyAsync(b=>b.TenantId==tenant&&(b.UserId==first&&b.BlockedUserId==second||b.UserId==second&&b.BlockedUserId==first));
 public async Task<IQueryable<Conversation>> Conversations(Guid tenant){var now=DateTimeOffset.UtcNow;var global=await community.Global(tenant,"communications.inbox").AnyAsync();var units=global?Array.Empty<Guid>():await a.Visible(tenant,"communications.inbox").Select(u=>u.Id).ToArrayAsync();var groupGlobal=await community.Global(tenant,"communications.groups").AnyAsync();var groupUnits=groupGlobal?Array.Empty<Guid>():await a.Visible(tenant,"communications.groups").Select(u=>u.Id).ToArrayAsync();var user=a.UserId;return db.Set<Conversation>().AsNoTracking().Where(c=>(c.Kind!="Group"||!db.Set<ConversationParticipant>().Any(p=>p.ConversationId==c.Id&&p.LeftAt==null&&db.Set<CommunityBlock>().Any(b=>b.TenantId==tenant&&(b.UserId==user&&b.BlockedUserId==p.UserId||b.UserId==p.UserId&&b.BlockedUserId==user))))&&c.TenantId==tenant&&((c.Kind=="Team"&&(global||c.UnitId!=null&&units.Contains(c.UnitId.Value)))||db.Set<ConversationParticipant>().Any(p=>p.TenantId==tenant&&p.ConversationId==c.Id&&p.UserId==user&&p.LeftAt==null&&((p.MembershipId==null&&(c.Kind=="Team"&&(global||c.UnitId!=null&&units.Contains(c.UnitId.Value))||c.Kind=="Group"&&(groupGlobal||c.UnitId!=null&&groupUnits.Contains(c.UnitId.Value))))||db.Memberships.Any(m=>m.Id==p.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)))))&&(c.Kind!="Direct"||(!db.Set<ConversationParticipant>().Any(p=>p.ConversationId==c.Id&&p.UserId!=user&&(p.LeftAt!=null||!db.Memberships.Any(m=>m.Id==p.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now))||db.Set<CommunityBlock>().Any(b=>b.TenantId==tenant&&(b.UserId==user&&b.BlockedUserId==p.UserId||b.UserId==p.UserId&&b.BlockedUserId==user))||db.Set<CommunicationPreference>().Any(pref=>pref.TenantId==tenant&&pref.UserId==p.UserId&&!pref.DirectMessages))))));}
 public async Task<Conversation> Conversation(Guid tenant,Guid id,bool write=false){await a.Member(tenant);var c=await (await Conversations(tenant)).SingleOrDefaultAsync(c=>c.Id==id)??throw new AccessDeniedException();if(c.Kind=="Direct"){if(!(await Preference(tenant,a.UserId)).DirectMessages)throw new AccessDeniedException();var peer=await db.Set<ConversationParticipant>().Where(p=>p.ConversationId==id&&p.UserId!=a.UserId&&p.LeftAt==null).FirstAsync();var directory=(await membership.Directory(tenant)).Select(m=>m.Id);if(!await directory.AnyAsync(m=>m==peer.MembershipId))throw new AccessDeniedException();}if(c.Kind=="Group"&&await db.Set<ConversationParticipant>().AnyAsync(p=>p.ConversationId==id&&p.LeftAt==null&&db.Set<CommunityBlock>().Any(b=>b.TenantId==tenant&&(b.UserId==a.UserId&&b.BlockedUserId==p.UserId||b.UserId==p.UserId&&b.BlockedUserId==a.UserId))))throw new AccessDeniedException();if(write){if(c.Status=="Archived")throw new DomainException("Conversation is archived");if(c.Kind=="Group"){var admin=await db.Set<ConversationParticipant>().AnyAsync(p=>p.ConversationId==id&&p.UserId==a.UserId&&p.LeftAt==null&&p.Role=="Admin");if(c.Posting=="Admins"&&!admin||c.Posting=="Officers"&&!await a.Can(tenant,"communications.groups",c.UnitId))throw new AccessDeniedException();}}return c;}
 public async Task<IQueryable<Membership>> Audience(Guid tenant,Guid? unit,AudienceRules rules){await a.Require(tenant,"communications.send",unit);if(rules.Match is not("AND" or "OR")||(rules.Filters??[]).Length>20)throw new DomainException("Use AND or OR with up to twenty audience filters");var units=a.InWorkspace(a.Visible(tenant,"communications.send"),tenant,unit).Select(u=>u.Id);var scope=db.Memberships.AsNoTracking().Where(m=>m.TenantId==tenant&&units.Contains(m.ChapterId));IQueryable<Membership> matched=rules.Match=="OR"?scope.Where(m=>false):scope;foreach(var f in rules.Filters??[]){if(f.Values.Length is <1 or >1000||f.Values.Any(v=>v.Length>300||v.Contains('\0')))throw new DomainException("Invalid audience filter values");var values=f.Values;Guid[] ids=[];if(new[]{"Chapter","Region","District","Category","Committee","EventRegistration","EventRsvp","EventAttendance"}.Contains(f.Key)){if(values.Any(v=>!Guid.TryParse(v,out _)))throw new DomainException("Filter identifiers are invalid");ids=values.Select(Guid.Parse).Distinct().ToArray();}
 IQueryable<Membership> part=scope;
 switch(f.Key){case "Chapter":case "Region":case "District":if(await a.Visible(tenant,"communications.send").CountAsync(u=>ids.Contains(u.Id))!=ids.Length)throw new AccessDeniedException();var descendants=db.Units.FromSqlInterpolated($"WITH RECURSIVE branch AS (SELECT * FROM \"Units\" WHERE \"TenantId\"={tenant} AND \"Id\"=ANY({ids}) UNION SELECT u.* FROM \"Units\" u JOIN branch b ON u.\"ParentId\"=b.\"Id\" WHERE u.\"TenantId\"={tenant}) SELECT * FROM branch").Select(u=>u.Id);part=part.Where(m=>descendants.Contains(m.ChapterId));break;
 case "Status":part=part.Where(m=>values.Contains(m.Status));break;case "Category":if(await db.MembershipCategories.CountAsync(c=>c.TenantId==tenant&&ids.Contains(c.Id))!=ids.Length)throw new AccessDeniedException();part=part.Where(m=>ids.Contains(m.CategoryId));break;
 case "Country":case "State":case "Language":var key=f.Key=="Language"?"languages":f.Key.ToLowerInvariant();var patterns=values.Select(v=>JsonSerializer.Serialize(new Dictionary<string,string>{{key,v}})).ToArray();part=part.Where(m=>patterns.Any(pattern=>EF.Functions.JsonContains(m.Profile,pattern)));break;
 case "JoinedAfter":case "JoinedBefore":if(values.Length!=1||!DateTimeOffset.TryParse(values[0],out var d))throw new DomainException("Use one valid joining date");d=d.ToUniversalTime();part=f.Key=="JoinedAfter"?part.Where(m=>m.JoinedAt>=d):part.Where(m=>m.JoinedAt<d);break;
 case "Officer":var now=DateTimeOffset.UtcNow;part=part.Where(m=>db.OfficerAppointments.Any(ap=>ap.TenantId==tenant&&ap.MembershipId==m.Id&&ap.Status=="Approved"&&ap.StartsAt<=now&&ap.EndsAt>now&&db.OfficerPositions.Any(pos=>pos.Id==ap.PositionId&&values.Contains(pos.Name))));break;
 case "Committee":if(await db.Committees.CountAsync(c=>c.TenantId==tenant&&ids.Contains(c.Id))!=ids.Length)throw new AccessDeniedException();var at=DateTimeOffset.UtcNow;part=part.Where(m=>db.CommitteeMemberships.Any(cm=>cm.TenantId==tenant&&cm.MembershipId==m.Id&&ids.Contains(cm.CommitteeId)&&cm.StartsAt<=at&&(cm.EndsAt==null||cm.EndsAt>at)));break;
 case "EventRegistration":case "EventRsvp":case "EventAttendance":foreach(var eventId in ids){var e=await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==eventId)??throw new AccessDeniedException();await a.Require(tenant,"communications.send",e.UnitId);}if(f.Key=="EventRegistration")part=part.Where(m=>db.Set<EventRegistration>().Any(r=>r.TenantId==tenant&&ids.Contains(r.EventId)&&r.MembershipId==m.Id&&r.Status=="Confirmed"));else if(f.Key=="EventAttendance")part=part.Where(m=>db.Set<EventAttendance>().Any(att=>att.TenantId==tenant&&!att.Voided&&ids.Contains(att.EventId)&&db.Set<EventRegistration>().Any(r=>r.Id==att.RegistrationId&&r.MembershipId==m.Id)));else part=part.Where(m=>db.Persons.Any(p=>p.Id==m.PersonId&&db.Set<EventRsvp>().Any(r=>r.TenantId==tenant&&r.UserId==p.UserId&&ids.Contains(r.EventId)&&r.Response=="Going")));break;
 default:throw new DomainException("Unknown audience filter: "+f.Key);}
 var partIds=part.Select(m=>m.Id);matched=rules.Match=="OR"?matched.Union(part):matched.Where(m=>partIds.Contains(m.Id));}
 if((rules.Filters??[]).Length==0)matched=scope;return matched;
 }
 public async Task<List<RecipientSnapshot>> Resolve(Guid tenant,IQueryable<Membership> query,string channel,Guid? eventId=null){if(!Channels.Contains(channel))throw new DomainException("Unsupported channel");var now=DateTimeOffset.UtcNow;var rows=await (from m in query join p in db.Persons on m.PersonId equals p.Id join u in db.Units on m.ChapterId equals u.Id join t in db.Tenants on m.TenantId equals t.Id select new{m,p.UserId,p.FullName,chapter=u.Name,society=t.Name}).Take(100001).ToListAsync();if(rows.Count>100000)throw new DomainException("Narrow this audience to 100,000 affiliations");var userIds=rows.Where(x=>x.UserId!=null).Select(x=>x.UserId!.Value).Distinct().ToArray();var prefs=await db.Set<CommunicationPreference>().Where(p=>p.TenantId==tenant&&userIds.Contains(p.UserId)).ToDictionaryAsync(p=>p.UserId);var emails=await db.Users.Where(u=>userIds.Contains(u.Id)).ToDictionaryAsync(u=>u.Id,u=>u.Email??"");var suppressions=await db.Set<CommunicationSuppression>().Where(s=>s.TenantId==tenant&&s.Channel==channel).Select(s=>s.DestinationHash).ToHashSetAsync();var e=eventId==null?null:await db.Set<CommunityEvent>().SingleOrDefaultAsync(e=>e.TenantId==tenant&&e.Id==eventId);var hierarchy=await (from u in db.Units join l in db.Levels on u.LevelId equals l.Id where u.TenantId==tenant select new{u.Id,u.ParentId,u.Name,l.Kind}).ToDictionaryAsync(u=>u.Id);var officer=await db.Users.Where(u=>u.Id==a.UserId).Select(u=>u.FullName).FirstOrDefaultAsync()??"";var result=new List<RecipientSnapshot>();foreach(var group in rows.GroupBy(x=>x.m.PersonId)){var row=group.OrderBy(x=>x.m.Id).First();var pref=row.UserId!=null&&prefs.TryGetValue(row.UserId.Value,out var saved)?saved:new CommunicationPreference();var profile=MembershipService.Json(row.m.Profile);var destination=channel=="InApp"?row.UserId?.ToString()??"":channel=="Email"?(row.UserId!=null?emails.GetValueOrDefault(row.UserId.Value,""):profile["email"]?.ToString()??""):profile["phone"]?.ToString()??"";var reason=group.Any(x=>x.m.Status!="Active"||x.m.EffectiveFrom>now||x.m.EndsAt<=now)?"Inactive":group.Any(x=>!CommunityService.CommunicationAllowed(x.m.Privacy))||!ChannelAllowed(pref,channel)?"Opted out":destination==""||channel=="Email"&&!System.Net.Mail.MailAddress.TryCreate(destination,out _)||channel is "SMS" or "WhatsApp"&&!Regex.IsMatch(destination,@"^\+[1-9][0-9]{7,14}$")?"Missing contact":suppressions.Contains(CommunityService.Hash(destination.ToLowerInvariant()))?"Suppressed":"Eligible";var region="";Guid? ancestor=row.m.ChapterId;for(var depth=0;depth<50&&ancestor!=null&&hierarchy.TryGetValue(ancestor.Value,out var branch);depth++){if(branch.Kind=="Region"){region=branch.Name;break;}ancestor=branch.ParentId;}var variables=new Dictionary<string,string>{{"member_name",row.FullName},{"chapter_name",row.chapter},{"society_name",row.society},{"region_name",region},{"officer_name",officer},{"event_name",e?.Title??""},{"event_date",e?.StartsAt.ToString("u")??""},{"event_venue",e?.Venue??""},{"rsvp_link",e==null?"":(config["PublicUrl"]??"").TrimEnd('/')+"/app/community/events/"+e.Id}};result.Add(new(row.m.Id,row.m.PersonId,row.UserId,row.FullName,row.m.ChapterId,destination,reason,group.Count()-1,variables));}return result;}
 public async Task Snapshot(CommunicationCampaign c){var rules=JsonSerializer.Deserialize<AudienceRules>(c.Audience,JsonOptions)!;var q=await Audience(c.TenantId,c.UnitId,rules);var recipients=await Resolve(c.TenantId,q,c.Channel,c.EventId);foreach(var r in recipients.Where(r=>r.Reason=="Eligible"))db.Add(new CampaignRecipient{TenantId=c.TenantId,CampaignId=c.Id,SnapshotVersion=c.SnapshotVersion,MembershipId=r.MembershipId,PersonId=r.PersonId,UserId=r.UserId,Destination=r.Destination,Variables=JsonSerializer.Serialize(r.Variables)});c.SnapshotCount=recipients.Count(r=>r.Reason=="Eligible");c.SnapshotAt=DateTimeOffset.UtcNow;if(c.SnapshotCount>(await Policy(c.TenantId)).HighVolumeThreshold)await a.Require(c.TenantId,"communications.highvolume",c.UnitId);}
 public static readonly JsonSerializerOptions JsonOptions=new(){PropertyNameCaseInsensitive=true};
 public void Notify(Guid tenant,Guid user,string title,string link,Guid resource,string key,string kind="Message"){db.Add(new CommunicationNotification{TenantId=tenant,UserId=user,Title=title,Link=link,ResourceId=resource,DedupKey=key,Kind=kind});}
 public static DateTimeOffset QuietUntil(CommunicationPreference p,DateTimeOffset now){var local=TimeZoneInfo.ConvertTime(now,TimeZoneInfo.FindSystemTimeZoneById(p.TimeZone));var hour=local.Hour;var quiet=p.QuietStart!=p.QuietEnd&&(p.QuietStart<p.QuietEnd?hour>=p.QuietStart&&hour<p.QuietEnd:hour>=p.QuietStart||hour<p.QuietEnd);if(!quiet)return now;var target=local.Date.AddHours(p.QuietEnd);if(target<=local.DateTime)target=target.AddDays(1);var zone=TimeZoneInfo.FindSystemTimeZoneById(p.TimeZone);while(zone.IsInvalidTime(target))target=target.AddHours(1);return new DateTimeOffset(TimeZoneInfo.ConvertTimeToUtc(target,zone),TimeSpan.Zero);}
}
public record RecipientSnapshot(Guid MembershipId,Guid PersonId,Guid? UserId,string Name,Guid ChapterId,string Destination,string Reason,int Duplicates,Dictionary<string,string> Variables);
[Microsoft.AspNetCore.Authorization.Authorize]
public class CommunicationHub:Hub {public override async Task OnConnectedAsync(){var http=Context.GetHttpContext();var origin=http?.Request.Headers.Origin.ToString();if(!string.IsNullOrEmpty(origin)&&Uri.TryCreate(origin,UriKind.Absolute,out var uri)&&!string.Equals(uri.Authority,http!.Request.Host.Value,StringComparison.OrdinalIgnoreCase)){Context.Abort();return;}await Groups.AddToGroupAsync(Context.ConnectionId,"user:"+Context.UserIdentifier);await base.OnConnectedAsync();}}
